// Initialize test suite
const saasUrl = $input.item.json.saasUrl;
if (!saasUrl) {
  throw new Error('SaaS URL is required');
}

const testCredentials = $input.item.json.testCredentials || {};
const testOptions = $input.item.json.testOptions || [];

// Setup test configuration
const testSuite = {
  url: saasUrl,
  timestamp: new Date().toISOString(),
  testOptions: testOptions,
  credentials: {
    hasCredentials: !!testCredentials.username && !!testCredentials.password,
    username: testCredentials.username || '',
    // We don't return the actual password for security
    hasPassword: !!testCredentials.password
  },
  pagesToTest: [
    { path: '/', name: 'Homepage' },
    { path: '/login', name: 'Login' },
    { path: '/signup', name: 'Signup' },
    { path: '/pricing', name: 'Pricing' },
    { path: '/contact', name: 'Contact' },
    { path: '/about', name: 'About' }
  ],
  responsiveBreakpoints: [
    { name: 'Mobile', width: 375, height: 667 },
    { name: 'Tablet', width: 768, height: 1024 },
    { name: 'Desktop', width: 1440, height: 900 }
  ]
};

return { json: testSuite };

// Process responsive test results
const page = $input.item.json;
const url = page.url;

const responsiveTests = {
  url: url,
  responsiveIssues: [],
  timestamp: new Date().toISOString()
};

// Simulate responsive testing (in real implementation, this would use Puppeteer to check viewport rendering)
const simulatedIssues = [
  {
    viewport: 'Mobile',
    element: 'header nav',
    issue: 'Overflow detected - elements extend beyond viewport',
    severity: 'high',
    position: { x: 0, y: 0 },
    recommendation: 'Implement a responsive mobile menu'
  },
  {
    viewport: 'Tablet',
    element: 'div.pricing-table',
    issue: 'Text overlapping in pricing tables',
    severity: 'medium',
    position: { x: 320, y: 450 },
    recommendation: 'Adjust font sizes or table spacing for tablet view'
  }
];

// Randomly assign issues based on the URL to simulate different problems on different pages
const urlHash = url.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
if (urlHash % 3 === 0) {
  responsiveTests.responsiveIssues.push(simulatedIssues[0]);
}
if (urlHash % 5 === 0) {
  responsiveTests.responsiveIssues.push(simulatedIssues[1]);
}

return { json: responsiveTests };

// Process form testing results
const page = $input.item.json;
const url = page.url;

// In a real implementation, this would extract actual forms using Puppeteer
// For demo, we'll simulate form detection and testing

const formTests = {
  url: url,
  formsFound: [],
  formIssues: [],
  timestamp: new Date().toISOString()
};

// Simulate form detection based on URL path
const urlPath = new URL(url).pathname.toLowerCase();

if (urlPath.includes('contact') || urlPath === '/') {
  formTests.formsFound.push({
    id: 'contact-form',
    action: '/api/contact',
    method: 'POST',
    fields: [
      { name: 'name', type: 'text', required: true },
      { name: 'email', type: 'email', required: true },
      { name: 'message', type: 'textarea', required: true }
    ]
  });

  // Simulate form issues
  formTests.formIssues.push({
    formId: 'contact-form',
    issue: 'Email validation allows invalid formats',
    severity: 'medium',
    recommendation: 'Enhance email validation on both client and server side'
  });
}

if (urlPath.includes('signup') || urlPath.includes('register')) {
  formTests.formsFound.push({
    id: 'signup-form',
    action: '/api/users',
    method: 'POST',
    fields: [
      { name: 'name', type: 'text', required: true },
      { name: 'email', type: 'email', required: true },
      { name: 'password', type: 'password', required: true },
      { name: 'confirm-password', type: 'password', required: true }
    ]
  });

  // Simulate form issues
  formTests.formIssues.push({
    formId: 'signup-form',
    issue: 'No password strength indicator',
    severity: 'low',
    recommendation: 'Add visual password strength feedback for users'
  });

  formTests.formIssues.push({
    formId: 'signup-form',
    issue: 'CSRF token missing',
    severity: 'high',
    recommendation: 'Implement CSRF protection for all forms'
  });
}

return { json: formTests };

// Process auth testing results
const page = $input.item.json;
const baseUrl = new URL(page.url).origin;

const authTests = {
  baseUrl: baseUrl,
  authIssues: [],
  timestamp: new Date().toISOString()
};

// Simulate auth testing (in real implementation, would use Puppeteer to actually test flows)

// Simulate checking for login page
const hasLoginPage = page.statusCode === 200;

// Check for password reset
let hasPasswordReset = false;
if (page.data && typeof page.data === 'string') {
  hasPasswordReset = page.data.includes('password') && 
                      (page.data.includes('forgot') || page.data.includes('reset'));
}

// Simulate auth issues
if (!hasLoginPage) {
  authTests.authIssues.push({
    issue: 'Login page not found or returns error',
    severity: 'high',
    path: '/login',
    recommendation: 'Implement a proper login page with username/email and password fields'
  });
}

if (!hasPasswordReset) {
  authTests.authIssues.push({
    issue: 'Password reset functionality not detected',
    severity: 'medium',
    path: '/login',
    recommendation: 'Add forgot password link and implement password reset flow'
  });
}

// Add simulated issues for demo purposes
authTests.authIssues.push({
  issue: 'No rate limiting on login attempts',
  severity: 'high',
  path: '/login',
  recommendation: 'Implement rate limiting to prevent brute force attacks'
});

authTests.authIssues.push({
  issue: 'Session timeout not properly configured',
  severity: 'medium',
  path: '/login',
  recommendation: 'Set appropriate session timeout and implement renewal mechanism'
});

return { json: authTests };

// Generate final report with actionable tasks
const allTests = [];

// Collect all test data
for (const item of $input.all()) {
  allTests.push(item.json);
}

// Original base URL
const baseUrlTest = allTests.find(test => test.url || test.baseUrl);
const baseUrl = baseUrlTest.url || baseUrlTest.baseUrl;

// Extract issues by type
const responsiveTests = allTests.filter(test => test.testType === 'responsiveness');
const formTests = allTests.filter(test => test.testType === 'forms');
const authTests = allTests.filter(test => test.testType === 'auth');

// Collect all issues
const responsiveIssues = responsiveTests.flatMap(test => test.responsiveIssues || []);
const formIssues = formTests.flatMap(test => test.formIssues || []);
const authIssues = authTests.flatMap(test => test.authIssues || []);

// Generate action items from issues
const generateActionItems = (issues, type) => {
  return issues.map(issue => ({
    taskId: `${type}-${Math.floor(Math.random() * 1000)}`,
    title: issue.issue || issue.description,
    category: type,
    severity: issue.severity || 'medium',
    description: `${issue.issue || ''} ${issue.recommendation ? '- ' + issue.recommendation : ''}`,
    additionalInfo: issue
  }));
};

const responsiveActions = generateActionItems(responsiveIssues, 'responsive');
const formActions = generateActionItems(formIssues, 'forms');
const authActions = generateActionItems(authIssues, 'auth');

// Add simulated navigation and performance tests for demonstration
const navigationActions = [
  {
    taskId: 'nav-123',
    title: 'Missing navigation links on mobile',
    category: 'navigation',
    severity: 'medium',
    description: 'The main navigation menu is missing critical links when viewed on mobile devices - Ensure all navigation items are available on all devices',
    additionalInfo: { element: 'nav.main-menu', viewport: 'Mobile' }
  },
  {
    taskId: 'nav-456',
    title: 'Broken link to documentation',
    category: 'navigation',
    severity: 'medium',
    description: 'Link to documentation page returns 404 - Create documentation page or update link',
    additionalInfo: { link: '/docs', statusCode: 404 }
  }
];

const performanceActions = [
  {
    taskId: 'perf-123',
    title: 'Unoptimized images on homepage',
    category: 'performance',
    severity: 'medium',
    description: 'Large uncompressed images detected on homepage - Optimize images to improve page load time',
    additionalInfo: { page: '/', resourceSize: '4.2MB' }
  },
  {
    taskId: 'perf-456',
    title: 'Excessive JavaScript loading',
    category: 'performance',
    severity: 'high',
    description: 'Too many JavaScript files being loaded synchronously - Combine and minify JavaScript files and use async loading where appropriate',
    additionalInfo: { jsFiles: 23, totalSize: '2.8MB' }
  }
];

// Combine all action items
const allActions = [
  ...responsiveActions,
  ...formActions,
  ...authActions,
  ...navigationActions,
  ...performanceActions
];

// Sort by severity
const severityOrder = { high: 0, medium: 1, low: 2 };
allActions.sort((a, b) => {
  return severityOrder[a.severity] - severityOrder[b.severity];
});

// Final report structure
const finalReport = {
  saasUrl: baseUrl,
  scanDate: new Date().toISOString(),
  summary: {
    totalIssues: allActions.length,
    highSeverity: allActions.filter(item => item.severity === 'high').length,
    mediumSeverity: allActions.filter(item => item.severity === 'medium').length,
    lowSeverity: allActions.filter(item => item.severity === 'low').length,
    categories: {
      responsive: responsiveActions.length,
      forms: formActions.length,
      auth: authActions.length,
      navigation: navigationActions.length,
      performance: performanceActions.length
    }
  },
  launchReadiness: allActions.filter(item => item.severity === 'high').length === 0 ? 'Ready with caution' : 'Not ready - critical issues found',
  actionItems: allActions,
  recommendations: {
    mustFix: allActions.filter(item => item.severity === 'high').map(item => item.title),
    shouldFix: allActions.filter(item => item.severity === 'medium').map(item => item.title),
    couldFix: allActions.filter(item => item.severity === 'low').map(item => item.title)
  }
};

return { json: finalReport };

// Expand base URL into a list of pages to test
const baseConfig = $input.item.json;
const baseUrl = baseConfig.url;

const expandedUrls = [];

// Generate URLs from the base configuration
for (const page of baseConfig.pagesToTest) {
  const fullUrl = new URL(page.path, baseUrl).toString();
  expandedUrls.push({
    ...baseConfig,
    url: fullUrl,
    pageName: page.name
  });
}

return [{ json: expandedUrls }];
